using UnityEngine;
using UnityEngine.UI;
using GoogleMobileAds.Api;
using TMPro;
using System.Collections.Generic;

/// <summary>
/// Quản lý Rewarded Interstitial Ad (xem quảng cáo nhận vàng).
/// Sử dụng Singleton để có thể gọi ở bất kỳ đâu trong game.
/// </summary>
public class RewardedGoldAd : MonoBehaviour
{
    // ---------- Singleton ---------- //
    public static RewardedGoldAd Instance { get; private set; }

    // ---------- UI References ---------- //
    [Header("UI")]
    public TextMeshProUGUI goldText;   // Hiển thị số vàng
    public Button watchAdButton;       // Nút bấm để xem quảng cáo

    // ---------- Gameplay Data ---------- //
    private int gold = 0;              
    private RewardedInterstitialAd rewardedInterstitialAd;

    // ---------- Ad Unit ID ---------- //
#if UNITY_ANDROID
    private string _adUnitId = "ca-app-pub-3940256099942544/5354046379"; // Test ID Android
#elif UNITY_IPHONE
    private string _adUnitId = "ca-app-pub-3940256099942544/6978759866"; // Test ID iOS
#else
    private string _adUnitId = "unused";
#endif

    // ---------- Unity Lifecycle ---------- //
    private void Awake()
    {
        // Setup Singleton
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject); // Giữ lại khi đổi scene
    }

    private void Start()
    {
        gold = 0;
        UpdateGoldText();

        if (watchAdButton != null)
            watchAdButton.onClick.AddListener(ShowRewardedInterstitialAd);

        // Thêm device ID cố định vào danh sách test devices
        List<string> testDeviceIds = new List<string> { "1c97557bda7ac517" };
        RequestConfiguration requestConfiguration = new RequestConfiguration
        {
            TestDeviceIds = testDeviceIds
        };
        MobileAds.SetRequestConfiguration(requestConfiguration);

        // Khởi tạo SDK
        MobileAds.Initialize((initStatus) =>
        {
            Debug.Log("Google Mobile Ads SDK initialized.");
            LoadRewardedInterstitialAd();
        });
    }

    private void OnDestroy()
    {
        DestroyAd();
    }

    // ---------- UI Update ---------- //
    /// <summary>
    /// Cập nhật số vàng hiển thị trên UI.
    /// </summary>
    private void UpdateGoldText()
    {
        if (goldText != null)
            goldText.text = "Gold: " + gold;
    }

    // ---------- Ad Logic ---------- //
    /// <summary>
    /// Load Rewarded Interstitial Ad mới.
    /// </summary>
    public void LoadRewardedInterstitialAd()
    {
        if (rewardedInterstitialAd != null)
        {
            rewardedInterstitialAd.Destroy();
            rewardedInterstitialAd = null;
        }

        AdRequest adRequest = new AdRequest();

        RewardedInterstitialAd.Load(_adUnitId, adRequest, (RewardedInterstitialAd ad, LoadAdError error) =>
        {
            if (error != null || ad == null)
            {
                Debug.LogError("Rewarded interstitial ad failed to load: " + error);
                return;
            }

            Debug.Log("Rewarded interstitial ad loaded successfully.");
            rewardedInterstitialAd = ad;
            RegisterEventHandlers(rewardedInterstitialAd);
        });
    }

    /// <summary>
    /// Hiển thị quảng cáo và cộng vàng khi người chơi nhận thưởng.
    /// </summary>
    public void ShowRewardedInterstitialAd()
    {
        if (rewardedInterstitialAd != null && rewardedInterstitialAd.CanShowAd())
        {
            rewardedInterstitialAd.Show((Reward reward) =>
            {
                gold += 100; // Cộng vàng khi xem xong
                UpdateGoldText();
                Debug.Log("Reward granted: +100 gold");
            });
        }
        else
        {
            Debug.Log("Rewarded interstitial ad is not ready.");
        }
    }

    /// <summary>
    /// Gắn các sự kiện callback cho quảng cáo.
    /// </summary>
    private void RegisterEventHandlers(RewardedInterstitialAd ad)
    {
        ad.OnAdPaid += (AdValue adValue) =>
        {
            Debug.Log($"Ad paid {adValue.Value} {adValue.CurrencyCode}");
        };
        ad.OnAdImpressionRecorded += () => Debug.Log("Ad impression recorded.");
        ad.OnAdClicked += () => Debug.Log("Ad clicked.");
        ad.OnAdFullScreenContentOpened += () => Debug.Log("Ad full screen opened.");
        ad.OnAdFullScreenContentClosed += () =>
        {
            Debug.Log("Ad closed. Reloading...");
            LoadRewardedInterstitialAd();
        };
        ad.OnAdFullScreenContentFailed += (AdError error) =>
        {
            Debug.LogError("Ad failed to open full screen: " + error);
            LoadRewardedInterstitialAd();
        };
    }

    /// <summary>
    /// Giải phóng bộ nhớ quảng cáo khi không dùng nữa.
    /// </summary>
    private void DestroyAd()
    {
        if (rewardedInterstitialAd != null)
        {
            rewardedInterstitialAd.Destroy();
            rewardedInterstitialAd = null;
        }
    }
}

using UnityEngine;

public class Singleton<T> : MonoBehaviour where T : MonoBehaviour
{
    private static T _instance;

    public static T Instance
    {
        get
        {
            if (_instance == null)
            {
                _instance = FindObjectOfType<T>();
                if (_instance == null)
                {
                    GameObject obj = new GameObject();
                    obj.name = typeof(T).Name;
                    _instance = obj.AddComponent<T>();
                }
            }
            return _instance;
        }
    }

    protected virtual void Awake()
    {
        if (_instance == null)
        {
            _instance = this as T;
            DontDestroyOnLoad(gameObject);
        }
        else if (_instance != this)
        {
            Destroy(gameObject);
        }
    }
}

using UnityEngine;
using System.Collections.Generic;

public class ObjectPool : MonoBehaviour
{
    public GameObject objectToPool;
    public int amountToPool;

    private List<GameObject> pooledObjects;

    void Start()
    {
        pooledObjects = new List<GameObject>();
        for (int i = 0; i < amountToPool; i++)
        {
            GameObject obj = Instantiate(objectToPool);
            obj.SetActive(false);
            pooledObjects.Add(obj);
        }
    }

    public GameObject GetPooledObject()
    {
        for (int i = 0; i < pooledObjects.Count; i++)
        {
            if (!pooledObjects[i].activeInHierarchy)
            {
                return pooledObjects[i];
            }
        }
        // If no inactive object is found, create a new one
        GameObject obj = Instantiate(objectToPool);
        pooledObjects.Add(obj);
        return obj;
    }

    public void ReturnObjectToPool(GameObject obj)
    {
        obj.SetActive(false);
    }
}

using UnityEngine;
using DG.Tweening;

public class DoTweenMove : MonoBehaviour
{
    public Vector3 endPosition = new Vector3(5, 0, 0);
    public float duration = 1f;
    public Ease easeType = Ease.OutQuad;

    void Start()
    {
        // Di chuyển đối tượng đến endPosition trong khoảng thời gian duration
        transform.DOMove(endPosition, duration).SetEase(easeType);
    }
}

using UnityEngine;
using DG.Tweening;

public class DoTweenScale : MonoBehaviour
{
    public Vector3 endScale = new Vector3(1.5f, 1.5f, 1.5f);
    public float duration = 0.5f;
    public Ease easeType = Ease.OutBack;

    void Start()
    {
        // Phóng to đối tượng lên endScale trong khoảng thời gian duration
        // SetLoops(-1, LoopType.Yoyo) để lặp lại hiệu ứng phóng to-thu nhỏ
        transform.DOScale(endScale, duration).SetEase(easeType).SetLoops(-1, LoopType.Yoyo);
    }
}

using UnityEngine;
using DG.Tweening;

public class DoTweenRotate : MonoBehaviour
{
    public Vector3 endRotation = new Vector3(0, 0, 360);
    public float duration = 2f;
    public RotateMode rotateMode = RotateMode.FastBeyond360;
    public Ease easeType = Ease.Linear;

    void Start()
    {
        // Xoay đối tượng 360 độ quanh trục Z
        // SetLoops(-1) để xoay vô hạn
        transform.DORotate(endRotation, duration, rotateMode).SetEase(easeType).SetLoops(-1, LoopType.Incremental);
    }
}

